    "legal_sources_note": "\u0643\u0644 \u0645\u0627\u062F\u0629 \u0642\u0627\u0646\u0648\u0646\u064A\u0629 \u0645\u0630\u0643\u0648\u0631\u0629 \u0647\u0646\u0627 \u062D\u0642\u064A\u0642\u064A\u0629 \u0648\u062A\u0645 \u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646\u0647\u0627 \u0639\u0628\u0631 \u0645\u0635\u0627\u062F\u0631 \u0642\u0627\u0646\u0648\u0646\u064A\u0629 \u0645\u0648\u062B\u0648\u0642\u0629. \u0644\u0643\u0646 '\u0627\u0644\u062A\u0641\u0633\u064A\u0631' \u0648'\u0633\u0628\u0628 \u0627\u0644\u062A\u0646\u0628\u064A\u0647' \u0641\u064A \u0643\u0644 \u0628\u0646\u062F \u0647\u0648 \u0634\u0631\u062D \u062A\u0628\u0633\u064A\u0637\u064A \u0623\u0639\u062F\u0647 Dalil \u0648\u0644\u064A\u0633 \u0646\u0635\u064B\u0627 \u0642\u0627\u0646\u0648\u0646\u064A\u064B\u0627 \u0631\u0633\u0645\u064A\u064B\u0627 \u0623\u0648 \u0631\u0623\u064A\u064B\u0627 \u0644\u0645\u062D\u0627\u0645\u064D. \u0627\u0644\u0642\u0648\u0627\u0646\u064A\u0646 \u0627\u0644\u062E\u0627\u0635\u0629 (\u0645\u062B\u0644 \u0642\u0648\u0627\u0646\u064A\u0646 \u0625\u064A\u062C\u0627\u0631 \u0627\u0644\u0623\u0645\u0627\u0643\u0646 \u0627\u0644\u0642\u062F\u064A\u0645\u0629\u060C \u0623\u0648 \u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u062A\u0645\u0648\u064A\u0644 \u0627\u0644\u0627\u0633\u062A\u0647\u0644\u0627\u0643\u064A \u0644\u0644\u0633\u064A\u0627\u0631\u0627\u062A) \u0642\u062F \u062A\u064F\u0642\u064A\u0651\u062F \u0623\u0648 \u062A\u064F\u0639\u062F\u0651\u0644 \u0628\u0639\u0636 \u0623\u062D\u0643\u0627\u0645 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0645\u062F\u0646\u064A \u0627\u0644\u0639\u0627\u0645 \u062D\u0633\u0628 \u0637\u0628\u064A\u0639\u0629 \u0627\u0644\u0639\u0642\u062F \u0648\u062A\u0627\u0631\u064A\u062E\u0647.",
    "disclaimer": "\u0647\u0630\u0647 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0644\u0623\u063A\u0631\u0627\u0636 \u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u062A\u0642\u062F\u064A\u0645\u064A (Hackathon MVP) \u0648\u0644\u064A\u0633\u062A \u0627\u0633\u062A\u0634\u0627\u0631\u0629 \u0642\u0627\u0646\u0648\u0646\u064A\u0629 \u0645\u0639\u062A\u0645\u062F\u0629. \u064A\u062C\u0628 \u0645\u0631\u0627\u062C\u0639\u0629 \u0645\u062D\u0627\u0645\u064D \u0645\u062E\u062A\u0635 \u0642\u0628\u0644 \u0627\u062A\u062E\u0627\u0630 \u0623\u064A \u0642\u0631\u0627\u0631 \u0642\u0627\u0646\u0648\u0646\u064A \u0628\u0646\u0627\u0621\u064B \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062A\u062D\u0644\u064A\u0644.",
