        "clause_pattern": "\u064A\u064F\u062C\u062F\u062F \u0627\u0644\u0639\u0642\u062F \u062A\u0644\u0642\u0627\u0626\u064A\u064B\u0627 \u0645\u0627 \u0644\u0645 \u064A\u064F\u062E\u0637\u0631 \u0623\u062D\u062F \u0627\u0644\u0637\u0631\u0641\u064A\u0646 \u0627\u0644\u0622\u062E\u0631 \u0628\u0631\u063A\u0628\u062A\u0647 \u0641\u064A \u0639\u062F\u0645 \u0627\u0644\u062A\u062C\u062F\u064A\u062F \u0642\u0628\u0644 60 \u064A\u0648\u0645\u064B\u0627 \u0645\u0646 \u0627\u0646\u062A\u0647\u0627\u0621 \u0627\u0644\u0645\u062F\u0629",
