        "legal_reference": "\u0627\u0644\u0639\u0642\u0648\u062F \u0627\u0644\u0639\u0631\u0641\u064A\u0629 \u063A\u064A\u0631 \u0627\u0644\u0645\u0633\u062C\u0644\u0629 \u062A\u0628\u0642\u0649 \u0645\u0644\u0632\u0645\u0629 \u0628\u064A\u0646 \u0637\u0631\u0641\u064A\u0647\u0627 \u0648\u0641\u0642\u064B\u0627 \u0644\u0644\u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0639\u0627\u0645\u0629 \u0644\u0644\u0639\u0642\u0648\u062F \u0641\u064A \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0645\u062F\u0646\u064A\u060C \u0644\u0643\u0646 \u0627\u0644\u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u0631\u0633\u0645\u064A \u064A\u0645\u0646\u062D \u062D\u062C\u064A\u0629 \u0623\u0642\u0648\u0649 \u0641\u064A \u0627\u0644\u0625\u062B\u0628\u0627\u062A \u0648\u0623\u0645\u0627\u0645 \u0627\u0644\u063A\u064A\u0631.",
