          "\u0627\u0644\u0645\u0627\u062F\u0629 21: \u064A\u062D\u0642 \u0644\u0644\u0645\u0633\u062A\u0647\u0644\u0643 \u062E\u0644\u0627\u0644 30 \u064A\u0648\u0645\u064B\u0627 \u0645\u0646 \u0627\u0644\u0627\u0633\u062A\u0644\u0627\u0645 \u0627\u0633\u062A\u0628\u062F\u0627\u0644 \u0623\u0648 \u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u0633\u0644\u0639\u0629 \u0645\u0639 \u0627\u0633\u062A\u0631\u062F\u0627\u062F \u0642\u064A\u0645\u062A\u0647\u0627 \u0625\u0630\u0627 \u0634\u0627\u0628\u0647\u0627 \u0639\u064A\u0628 \u0623\u0648 \u0643\u0627\u0646\u062A \u063A\u064A\u0631 \u0645\u0637\u0627\u0628\u0642\u0629 \u0644\u0644\u0645\u0648\u0627\u0635\u0641\u0627\u062A (\u0645\u0639 \u0627\u0633\u062A\u062B\u0646\u0627\u0621\u0627\u062A \u0645\u062D\u062F\u062F\u0629 \u0641\u064A \u0627\u0644\u0644\u0627\u0626\u062D\u0629 \u0627\u0644\u062A\u0646\u0641\u064A\u0630\u064A\u0629).",
          "\u0627\u0644\u0645\u0627\u062F\u0629 22: \u0636\u0645\u0627\u0646 \u0642\u0627\u0646\u0648\u0646\u064A \u0625\u0644\u0632\u0627\u0645\u064A \u0644\u0645\u062F\u0629 \u0633\u0646\u062A\u064A\u0646 \u0639\u0644\u0649 \u0627\u0644\u0633\u0644\u0639 \u0627\u0644\u0645\u062D\u0644\u064A\u0629 \u0648\u0627\u0644\u0645\u0633\u062A\u0648\u0631\u062F\u0629 (\u062A\u0634\u0645\u0644 \u0627\u0644\u0633\u064A\u0627\u0631\u0627\u062A) \u0628\u0635\u0631\u0641 \u0627\u0644\u0646\u0638\u0631 \u0639\u0646 \u0648\u062C\u0648\u062F \u0634\u0647\u0627\u062F\u0629 \u0636\u0645\u0627\u0646 \u0645\u0646 \u0627\u0644\u0634\u0631\u0643\u0629 \u0623\u0645 \u0644\u0627.",
          "\u0627\u0644\u0645\u0627\u062F\u0629 23: \u064A\u0644\u062A\u0632\u0645 \u0627\u0644\u062A\u0627\u062C\u0631/\u0627\u0644\u0648\u0643\u064A\u0644 \u0628\u062A\u0648\u0641\u064A\u0631 \u0642\u0637\u0639 \u0627\u0644\u063A\u064A\u0627\u0631 \u0648\u0645\u0631\u0627\u0643\u0632 \u0627\u0644\u0635\u064A\u0627\u0646\u0629 \u0644\u0645\u062F\u0629 '\u0627\u0644\u0639\u0645\u0631 \u0627\u0644\u0627\u0641\u062A\u0631\u0627\u0636\u064A' \u0644\u0644\u0633\u0644\u0639\u0629 \u0627\u0644\u0645\u062D\u062F\u062F \u0641\u064A \u0628\u064A\u0627\u0646\u0627\u062A\u0647\u0627.",
