        "relevance": "\u0647\u0630\u0647 \u0647\u064A \u0627\u0644\u0645\u0627\u062F\u0629 \u0627\u0644\u0623\u0647\u0645 \u0644\u0645\u0634\u0631\u0648\u0639 Dalil \u2014 \u0627\u0644\u0623\u0633\u0627\u0633 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064A \u0627\u0644\u0630\u064A \u064A\u0628\u0631\u0631 \u062A\u0635\u0646\u064A\u0641 \u0628\u0646\u062F \u0645\u0627 \u0628\u0623\u0646\u0647 '\u064A\u0633\u062A\u062D\u0642 \u0627\u0644\u0627\u0646\u062A\u0628\u0627\u0647' \u0644\u0623\u0646\u0647 \u062A\u0639\u0633\u0641\u064A\u060C \u0644\u0623\u0646 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0646\u0641\u0633\u0647 \u064A\u0645\u0646\u062D \u0627\u0644\u0642\u0627\u0636\u064A \u0633\u0644\u0637\u0629 \u062A\u0639\u062F\u064A\u0644\u0647."
